  glVertex3f(-1, -0.3f, 0.8f);
  glColor3f(1, 1, 0);
  glVertex3f(-1, 0.9f, 0.1f);
  glColor3f(0, 1, 1);
  glVertex3f(0.2f, 0.9f, 0.1f);
  glColor3f(1, 0, 1);
  glVertex3f(-1, -0.2f, 0.1f);
  glEnd();
}

